Here’s a small Flask app that stores uploaded files on the server and gives you a shareable link. Visitors must enter the password you chose before downloading.

### 1. Install Flask

```bash
pip install flask
```

### 2. Save as `app.py`

```python
import secrets
import sqlite3
from pathlib import Path

from flask import (
    Flask, abort, render_template_string, request,
    send_file, url_for
)
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = 100 * 1024 * 1024  # 100 MB

DATA = Path("data")
UPLOADS = DATA / "uploads"
UPLOADS.mkdir(parents=True, exist_ok=True)
DATABASE = DATA / "files.db"


def connect():
    db = sqlite3.connect(DATABASE)
    db.row_factory = sqlite3.Row
    return db


with connect() as db:
    db.execute("""
        CREATE TABLE IF NOT EXISTS files (
            id TEXT PRIMARY KEY,
            filename TEXT NOT NULL,
            password_hash TEXT NOT NULL
        )
    """)


PAGE = """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{ title }}</title>
  <style>
    body { font: 16px system-ui, sans-serif; background: #f3f5f9;
           color: #182033; margin: 0; padding: 2rem 1rem; }
    main { max-width: 480px; margin: 3rem auto; background: white;
           padding: 2rem; border-radius: 12px;
           box-shadow: 0 4px 24px #0001; }
    label { display: block; font-weight: 600; margin: 1rem 0 .4rem; }
    input { box-sizing: border-box; width: 100%; padding: .7rem;
            border: 1px solid #b8c1d1; border-radius: 6px; }
    button { margin-top: 1.2rem; padding: .75rem 1rem; border: 0;
             border-radius: 6px; background: #3458db; color: white;
             font-size: 1rem; cursor: pointer; }
    .error { color: #b42318; }
    .link { overflow-wrap: anywhere; }
    .hint { color: #566; font-size: .9rem; }
  </style>
</head>
<body><main>
  <h1>{{ title }}</h1>
  {% if error %}<p class="error">{{ error }}</p>{% endif %}

  {% if mode == "upload" %}
    <p>Upload a file and protect it with a password.</p>
    <form method="post" enctype="multipart/form-data">
      <label for="file">File</label>
      <input id="file" name="file" type="file" required>
      <label for="password">Password</label>
      <input id="password" name="password" type="password"
             maxlength="256" required>
      <p class="hint">Maximum file size: 100 MB.</p>
      <button type="submit">Upload</button>
    </form>
  {% elif mode == "success" %}
    <p>Share this link with your friends:</p>
    <p class="link"><a href="{{ link }}">{{ link }}</a></p>
    <p class="hint">Send the password separately.</p>
    <a href="{{ url_for('index') }}">Share another file</a>
  {% elif mode == "download" %}
    <p>Enter the password to download <strong>{{ filename }}</strong>.</p>
    <form method="post">
      <label for="password">Password</label>
      <input id="password" name="password" type="password"
             maxlength="256" required>
      <button type="submit">Download</button>
    </form>
  {% endif %}
</main></body>
</html>
"""


@app.route("/", methods=["GET", "POST"])
def index():
    if request.method == "POST":
        upload = request.files.get("file")
        password = request.form.get("password", "")

        if not upload or not upload.filename or not password or len(password) > 256:
            return render_template_string(
                PAGE, title="Share a file", mode="upload",
                error="Choose a file and a password of 1–256 characters."
            ), 400

        filename = secure_filename(upload.filename) or "download"
        file_id = secrets.token_urlsafe(32)
        path = UPLOADS / file_id

        upload.save(path)
        try:
            with connect() as db:
                db.execute(
                    "INSERT INTO files (id, filename, password_hash) VALUES (?, ?, ?)",
                    (file_id, filename, generate_password_hash(password))
                )
        except Exception:
            path.unlink(missing_ok=True)
            raise

        link = url_for("download", file_id=file_id, _external=True)
        return render_template_string(
            PAGE, title="File uploaded", mode="success", link=link
        )

    return render_template_string(PAGE, title="Share a file", mode="upload")


@app.route("/file/<file_id>", methods=["GET", "POST"])
def download(file_id):
    with connect() as db:
        record = db.execute(
            "SELECT * FROM files WHERE id = ?", (file_id,)
        ).fetchone()

    if record is None:
        abort(404)

    if request.method == "POST":
        password = request.form.get("password", "")
        if len(password) <= 256 and check_password_hash(record["password_hash"], password):
            path = UPLOADS / record["id"]
            if not path.is_file():
                abort(404)
            response = send_file(
                path, as_attachment=True, download_name=record["filename"]
            )
            response.headers["Cache-Control"] = "no-store"
            return response

        return render_template_string(
            PAGE, title="Download file", mode="download",
            filename=record["filename"], error="Incorrect password."
        ), 403

    return render_template_string(
        PAGE, title="Download file", mode="download",
        filename=record["filename"]
    )


@app.errorhandler(413)
def too_large(error):
    return "File is too large. The maximum upload size is 100 MB.", 413


if __name__ == "__main__":
    app.run(port=5000)
```

### 3. Run it

```bash
python app.py
```

Open **http://127.0.0.1:5000**, upload a file, and choose a password.

**To share with friends**, deploy the app on a publicly accessible server; a localhost link only works on your own computer. Use HTTPS and add password-attempt rate limiting before exposing it publicly. Files remain on the server until you manually delete them, and the `data` directory must not be publicly served.

